      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rd(data, 170, 32)
      v = rv
      w = w ||| v <<< 32
      v_nonce = w

      value = %Example.ProbeBits{
        small: v_small,
        boundary: v_boundary,
        wide: v_wide,
        sensor: v_sensor,
