  @doc """
  The §5 zero form of ProbeSample: all-zero storage. Specified defaults live
  only in construction (`%Example.ProbeSample{}`).
  """
  @spec zero_probe_sample() :: Example.ProbeSample.t()
  def zero_probe_sample do
    %Example.ProbeSample{
      active: false,
      orientation: 0.0,
      raw_delta: 0,
      big_delta: 0,
      weapon: :none,
      has_target: false,
      target_id: 0,
      idle_ticks: 0,
