          scratch = scratch ||| v <<< 2
          v = value_shape_slab_height &&& 0xFF
          scratch = scratch ||| v <<< 9
          data = <<data::binary, scratch::little-size(2)-unit(8)>>
          scratch = scratch >>> 16
          scratch_bits = 1
